package com.alsafa.native4;

import android.app.Activity;import android.graphics.Color;import android.os.Handler;import android.os.Looper;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.CheckBox;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.AdvancedSaleStore;import com.alsafa.native4.core.CoreProductCatalog;import com.alsafa.native4.core.CustomerCatalog;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;import com.alsafa.native4.core.SplitPaymentStore;import java.util.ArrayList;import java.util.List;
/** Core sale bridge styled to match the familiar AlSafa sale flow, with independent amount/currency/account per payment leg. */
public final class CoreSalePanelBinder {
 private static final int INK=Color.rgb(62,52,41),MUTED=Color.rgb(138,123,108),PAPER=Color.rgb(255,253,249),SAND=Color.rgb(234,217,185),GOLD=Color.rgb(122,81,24);
 private final Activity a;private final Native4Services services;private final TextView status,selected,selectedCustomer;private final EditText search,qty,productId,customerSearch,customerId;private final Spinner currency;private final LinearLayout results,paymentRows,customerResults;private final CheckBox allowDue;private final CoreProductCatalog catalog;private final CustomerCatalog customers;private final Handler handler=new Handler(Looper.getMainLooper());private Runnable pending,customerPending;private String lastQuery="",lastCustomerQuery="";
 public CoreSalePanelBinder(Activity a,Native4Services services,TextView status){this.a=a;this.services=services;this.status=status;DeveloperDashboardPanelBinder.attach(a,services);bindDayRefresh(a);catalog=new CoreProductCatalog(services.db);customers=new CustomerCatalog(services.db);customerSearch=a.findViewById(R.id.saleCustomerSearch);customerId=a.findViewById(R.id.saleCustomerId);selectedCustomer=a.findViewById(R.id.saleSelectedCustomer);customerResults=a.findViewById(R.id.saleCustomerResults);search=a.findViewById(R.id.saleSearch);qty=a.findViewById(R.id.saleQuantity);currency=a.findViewById(R.id.saleCurrency);currency.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));productId=a.findViewById(R.id.saleProductId);results=a.findViewById(R.id.saleSearchResults);selected=a.findViewById(R.id.saleSelectedProduct);paymentRows=a.findViewById(R.id.salePaymentRows);allowDue=a.findViewById(R.id.saleAllowDue);styleSaleUi();a.findViewById(R.id.searchSaleProduct).setOnClickListener(v->searchNow(true));a.findViewById(R.id.addSalePayment).setOnClickListener(v->addPaymentRow(null));a.findViewById(R.id.saveSale).setOnClickListener(v->save());customerSearch.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int b,int c){deferCustomerSearch();}public void afterTextChanged(android.text.Editable e){}});search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int b,int c){deferSearch();}public void afterTextChanged(android.text.Editable e){}});addPaymentRow(null);}
 private void styleSaleUi(){search.setHint("اسم الساعة أو الباركود");search.setTextSize(18);search.setTextColor(INK);search.setHintTextColor(MUTED);search.setBackgroundResource(R.drawable.alsafa_card);search.setPadding(dp(14),dp(12),dp(14),dp(12));qty.setHint("الكمية");qty.setTextSize(17);qty.setTextColor(INK);qty.setHintTextColor(MUTED);selected.setText("ابحث عن الساعة ثم اخترها من النتائج");selected.setTextColor(GOLD);selected.setTextSize(16);selected.setGravity(Gravity.END);selected.setPadding(dp(10),dp(12),dp(10),dp(12));Button searchButton=a.findViewById(R.id.searchSaleProduct);searchButton.setText("بحث عن الساعة");searchButton.setTextColor(INK);searchButton.setBackgroundResource(R.drawable.alsafa_card);Button add=a.findViewById(R.id.addSalePayment);add.setText("+ إضافة طريقة دفع أخرى");add.setTextColor(INK);add.setBackgroundResource(R.drawable.alsafa_card);Button save=a.findViewById(R.id.saveSale);save.setText("تثبيت المبيع");save.setTextSize(18);save.setTextColor(Color.WHITE);save.setMinHeight(dp(58));save.setBackgroundResource(R.drawable.alsafa_primary);}
 private static void bindDayRefresh(Activity a){int[] ids={R.id.openWorkDay,R.id.useLatestCarry,R.id.closeWorkDay};for(int id:ids){View v=a.findViewById(id);if(v!=null)v.addOnLayoutChangeListener((view,l,t,r,b,ol,ot,or_,ob)->DeveloperDashboardPanelBinder.refreshActive());}}
 private void addPaymentRow(String amount){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(10),dp(8),dp(10),dp(10));box.setBackgroundResource(R.drawable.alsafa_card);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);bp.setMargins(0,dp(6),0,dp(6));box.setLayoutParams(bp);TextView label=new TextView(a);label.setText("دفعة");label.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);label.setTextColor(INK);label.setGravity(Gravity.END);EditText value=new EditText(a);value.setHint("المبلغ المقبوض");value.setTextColor(INK);value.setHintTextColor(MUTED);value.setTextSize(17);value.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);if(amount!=null)value.setText(amount);Spinner cur=new Spinner(a);cur.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));Spinner account=new Spinner(a);String[] accounts={"الدرج","شام كاش","الخزنة الخارجية","البنك"};account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,accounts));Button remove=new Button(a);remove.setText("حذف الدفعة");remove.setTextColor(MUTED);remove.setBackgroundTintList(android.content.res.ColorStateList.valueOf(PAPER));remove.setOnClickListener(v->{if(paymentRows.getChildCount()>1)paymentRows.removeView(box);else value.setText("");});box.addView(label);box.addView(value);box.addView(cur);box.addView(account);box.addView(remove);box.setTag(new PaymentViews(value,cur,account));paymentRows.addView(box);}
 private List<SplitPaymentStore.Payment> readPayments(){List<SplitPaymentStore.Payment> out=new ArrayList<>();for(int i=0;i<paymentRows.getChildCount();i++){View row=paymentRows.getChildAt(i);PaymentViews p=(PaymentViews)row.getTag();String raw=p.amount.getText().toString().trim();if(raw.isEmpty())continue;double amount=Double.parseDouble(raw);String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,p.currency.getSelectedItemPosition());String account=accountCode(p.account.getSelectedItemPosition());String method="SHAM_CASH".equals(account)?"SHAM_CASH":"CASH";out.add(new SplitPaymentStore.Payment(amount,cur,method,account));}return out;}
 private static String accountCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";return "MAIN";}
 private void deferCustomerSearch(){if(customerPending!=null)handler.removeCallbacks(customerPending);String q=customerSearch.getText().toString().trim();if(q.length()<2){lastCustomerQuery="";customerResults.removeAllViews();customerId.setText("");selectedCustomer.setText("بدون عميل محدد");return;}customerPending=()->searchCustomers();handler.postDelayed(customerPending,325);}
 private void searchCustomers(){try{String q=customerSearch.getText().toString().trim();if(q.equals(lastCustomerQuery))return;lastCustomerQuery=q;customerResults.removeAllViews();for(CustomerCatalog.Hit h:customers.search(q,20)){Button b=new Button(a);b.setAllCaps(false);b.setText(h.label());b.setGravity(Gravity.CENTER_VERTICAL|Gravity.END);b.setBackgroundResource(R.drawable.alsafa_card);b.setOnClickListener(v->{customerId.setText(h.id);selectedCustomer.setText("✓ "+h.label());lastCustomerQuery=h.name;customerSearch.setText(h.name);customerSearch.setSelection(customerSearch.length());customerResults.removeAllViews();});customerResults.addView(b);}}catch(Exception e){status.setText("تعذر بحث العميل: "+msg(e));}}
 private void deferSearch(){if(pending!=null)handler.removeCallbacks(pending);String q=search.getText().toString().trim();if(q.length()<2){lastQuery="";results.removeAllViews();return;}pending=()->searchNow(false);handler.postDelayed(pending,325);}
 private void searchNow(boolean force){try{String q=search.getText().toString().trim();if(!force&&q.equals(lastQuery))return;lastQuery=q;results.removeAllViews();List<CoreProductCatalog.ProductHit> hits=catalog.search(q,20);for(CoreProductCatalog.ProductHit h:hits){Button b=new Button(a);b.setAllCaps(false);b.setText(h.label());b.setGravity(Gravity.CENTER_VERTICAL|Gravity.END);b.setMinHeight(dp(64));b.setTextSize(17);b.setTextColor(INK);b.setBackgroundResource(R.drawable.alsafa_card);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.setMargins(0,dp(3),0,dp(3));b.setLayoutParams(lp);b.setOnClickListener(v->select(h));results.addView(b);}if(hits.isEmpty()){TextView t=new TextView(a);t.setText("لا توجد ساعة مطابقة");t.setTextColor(MUTED);t.setGravity(Gravity.END);t.setPadding(dp(12),dp(14),dp(12),dp(14));results.addView(t);}}catch(Exception e){status.setText("تعذر البحث: "+msg(e));}}
 private void select(CoreProductCatalog.ProductHit h){if(pending!=null)handler.removeCallbacks(pending);productId.setText(h.id);selected.setText("✓ "+h.label());lastQuery=h.name;search.setText(h.name);search.setSelection(search.length());results.removeAllViews();status.setText("تم اختيار الساعة — أكمل الكمية والدفع");}
 private void save(){try{String id=productId.getText().toString().trim();if(id.isEmpty())throw new IllegalArgumentException("اختر الساعة أولاً");int q=Integer.parseInt(qty.getText().toString().trim());String invoiceCur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition());List<SplitPaymentStore.Payment> payments=readPayments();if(payments.isEmpty()&&!allowDue.isChecked())throw new IllegalArgumentException("أدخل دفعة واحدة على الأقل أو فعّل البيع الآجل");AdvancedSaleStore.Result r=services.sales.saleSplit(id,q,customerId.getText().toString().trim(),0,invoiceCur,payments,0,allowDue.isChecked());Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();status.setText("✓ تمت الفاتورة "+r.invoiceNo+" — "+fmt(r.total)+" "+invoiceCur+" — "+payments.size()+" دفعة");qty.setText("");productId.setText("");selected.setText("ابحث عن الساعة ثم اخترها من النتائج");lastQuery="";search.setText("");results.removeAllViews();customerId.setText("");customerSearch.setText("");selectedCustomer.setText("بدون عميل محدد");customerResults.removeAllViews();lastCustomerQuery="";paymentRows.removeAllViews();allowDue.setChecked(false);addPaymentRow(null);}catch(Exception e){status.setText("لم تُنفذ الفاتورة: "+msg(e));}}
 private static final class PaymentViews{final EditText amount;final Spinner currency,account;PaymentViews(EditText a,Spinner c,Spinner ac){amount=a;currency=c;account=ac;}}
 private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}
